// Einfache Review-Übersicht als HTML-Seite. Werte werden escaped, weil Mailtexte von außen kommen.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const zeilen = $input.all().map((i) => i.json).filter((r) => r.id);

const karten = zeilen.map((r) => `
  <article>
    <h2>#${esc(r.id)} · ${esc(r.betreff)}</h2>
    <p class="meta">${esc(r.absender)} · ${esc(r.erstellt)}</p>
    <p><b>Gründe:</b> ${r.gruende.map((g) => `<span class="tag">${esc(g)}</span>`).join(' ')}</p>
    <p><b>Vorschlag des LLM:</b> ${esc(r.vorschlag ?? '–')} (Konfidenz ${esc(r.konfidenz ?? '–')}) – ${esc(r.begruendung ?? '')}</p>
    <details><summary>Mailtext</summary><pre>${esc(r.text)}</pre></details>
  </article>`).join('');

const html = `<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Review-Queue</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 860px; margin: 2rem auto; padding: 0 1rem; color: #1f2328; }
  article { border: 1px solid #d0d7de; border-radius: 8px; padding: 1rem 1.25rem; margin-bottom: 1rem; }
  h2 { font-size: 1.05rem; margin: 0 0 .25rem; } .meta { color: #656d76; margin: 0 0 .75rem; }
  .tag { background: #fff1e5; color: #9a4b00; border-radius: 4px; padding: .1rem .4rem; font-size: .85rem; }
  pre { white-space: pre-wrap; background: #f6f8fa; padding: .75rem; border-radius: 6px; }
  a.button { display: inline-block; background: #1f6feb; color: #fff; padding: .5rem 1rem; border-radius: 6px; text-decoration: none; }
</style></head><body>
<h1>Review-Queue · ${zeilen.length} offen</h1>
<p><a class="button" href="/form/review">Review abschließen</a></p>
${karten || '<p>Keine offenen Reviews.</p>'}
</body></html>`;

return { json: { html } };
